import{_ as p,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const h=JSON.parse('{"title":"學易筆談述旨","description":"杭氏易學 - 學易筆談述旨","frontmatter":{"title":"學易筆談述旨","description":"杭氏易學 - 學易筆談述旨"},"headers":[],"relativePath":"classics/hangshi/021.md","filePath":"classics/hangshi/021.md"}'),r={name:"classics/hangshi/021.md"};function i(n,a,c,_,o,l){return t(),e("div",null,[...a[0]||(a[0]=[s('<h1 id="學易筆談述旨" tabindex="-1">學易筆談述旨 <a class="header-anchor" href="#學易筆談述旨" aria-label="Permalink to “學易筆談述旨”">​</a></h1><p>《易》道至大，《易》理至遂；辛齋之愚，何敢妄談？顧念吾師忍死狴犴，剋期以待，密傳心法，冀綿絕學，又曷敢自棄？丙辰出獄，爰蒐集古今說《易》之書，惟日孳孳，寢饋舟車，未嘗或輟。丁巳以後，國會蒙塵。播越嶺嶠，議席多暇，兩院同人，合組研幾學社於廣州之迥龍社。謬推都講，計日分程，商兌講習。雖兵戈擾攘，而課約罔閒。講義纂輯，得書若干，名曰《易楔》。而晨昏餘晷，切磋問難，隨時筆錄者，又積稿盈尺。同人艱於傳寫，乃謀刊印。釐為四卷，名曰《筆談》，蓋紀實焉。己未庚申，由粵而滬。同志之友，聞聲畢集。風雨一廬，不廢討論。以續前稿，又得四卷，另為《二集》。借閱傳鈔，恐多遺失。適前印之書，久已告罄。同人請合兩《集》與《易楔》、《易數偶得》、《讀易雜記》諸稿，均以聚珍板印行。始於壬戌八月，至十月抄，《筆談》八卷工竣。爰紀顛末，並述旨如左。</p><p>一、承學之士，不廢筆札，談論所及，擇要綴錄，聊以備忘。除《初集》第一卷，於臨印時略有增減，以明源流外，餘悉隨時編訂，並無先後次序。</p><p>二、講《易》與詁經不同。詁經當有家法，有體例，義不容雜。而講《易》則以闡明卦爻象數之原理原則，但以經文為之證明。故凡與象數有涉，足與《易》道相發明者，博採旁搜，不限時地，更無所謂門戶派別也。</p><p>三、《易》本法象於天地。乾易坤簡，易知易能，雖見仁見智，各隨學識之深淺而異，要無不可知之理。自象義不明，學者無所適從，幾視《易》為絕學，而不敢問津。致《易》簡之理，日即湮晦。本編有鑑於斯，立說皆取淺顯明 白，務期盡人能解，不敢以艱深文淺陋也。</p><p>四、孔子贊《易》，身逢亂世，行危言遜。有因時忌不能顯言者，不得不以微言大義，隱寓於象數之中，與春秋同一例也。後人不察，悉以文字求之，孔子憂天憫人之苦心湮沒盡矣。歷代學者，如邵康節，如劉青田、黃姚江，均抱此隱痛而未敢昌言者也。鼎革以後，世雖亂而言可無諱。發歷聖之心傳，彌前賢之遺憾，維世道而存絕學，不可謂非千載一時之良機。剝極必復，時乎不再，幸我同人勿自暴棄以負天心也。</p><p>五、卦因數衍，數緣象起，象由心生。《易》準天地，廣大悉備。雖人事遞演，世變日繁，要不能出乎此象數之外。故洲殊種別，文字語言，萬有不齊，維數足以齊之。宗教俗尚，各有不同，惟數足以同之。兩千年來，數學失傳。宋後言《易》者，往往以邵子先天數為《易》數。數理繁嘖，固非短扎所能盡。然於舊說之顯然挑牴牾者，不能不援據象數以為商榷，非敢故翻成案也。</p><p>六、占筮固《易》之一端，而聖人修《易》以明道，實非盡為占筮。孔子贊《易》，紹述文周，以人合天，兢兢寡過，豈導人於趨吉避凶哉！朱子以占筮為《易》之本義，未免偏見。而《大衍》揲蓍之法，自唐以後，於掛一再扐兩端，立說互歧。往諸數理，並多遺憾。未敢盲從，以誤後人。</p><p>七、至誠之道，雖可前知，惟道本一貫，學無躐等。必正心修身，能盡人之道以合天，斯天人契合，感而遂通，百世可知。初無二理。若一知半解，妄談禍福，自欺欺人，實學《易》之大戒。兢兢自箴者，竊願以此勉人。</p><p>八、儘性至命，乃易學之極功。孔子之聖，猶韋編三絕，但云寡過，罕言性命。後生末學，更宜踐履篤實，下學上達。同學講習，竊本斯旨。《初集》刊佈，朋自遠來，往往以只言象數，不談身心性命相責。但愚尚以象數之未能盡明為憾。果象數通解，則身心性命之理，胥在其中，更無待言說為也。</p><p>九、形而下者謂之器，形而上者謂之道。凡有形可指者皆器。道本於心，未可以言盡焉。故八卦因重，羲農法天以垂象；兩編《十翼》，周孔立言以明道。然未可遽執卦象經傳以為道也。譬諸升高必以梯，而梯非高。求飽必以飯，而飯非飽。宋後講《易》，開口言性理，言道統，是猶指梯而稱高，看飯而說飽也。今之談道者，無宋人之學，而立說更高出宋人。自誤誤人，更不待言。願學者共明斯旨，各求實學，返諸身心。勿好高鶩遠，循前車之覆轍焉。</p><p>十、潔淨精微之學，非潛修靜養，未能深造。勞人草草，敢言心得？惟匯積年涉獵所得，聊供同學參考之便。深望海內鴻碩，時加匡正。幸得學與年進，尚擬續，以供採擇。</p><p>十一、世道陵夷，聖學中絕。人慾橫流，罔知紀極。謹願之士，苦身心之無所寄託，蒿目時艱，恆懷消極。或附託西教，或皈向佛門。而仙靈神鬼，導引修養，及飛鸞顯化之壇宇，遂遍於域中。影附風從，是丹非素。不知我國固有之學，貫澈天人，足以安身立命。保世滋大，概群藉而羅萬有者，悉在此一畫開天，人文肇始之《易經》。存人道，挽世運，千鈞一髮，絕續在茲。弘道救世，責無旁貸。惟我同人，自奮勉焉。</p>',13)])])}const f=p(r,[["render",i]]);export{h as __pageData,f as default};
